const geo = {box:new THREE.BoxGeometry(1,1,1),sphere:new THREE.IcosahedronGeometry(1,1),cone:new THREE.ConeGeometry(1,1,5),cylinder:new THREE.CylinderGeometry(1,1,1,10)};
const mats={};
function mat(color,emissive=0){const key=color+'_'+emissive;return mats[key]??=new THREE.MeshStandardMaterial({color,roughness:.85,metalness:.12,emissive:color,emissiveIntensity:emissive});}
function mesh(g,m,x=0,y=0,z=0,sx=1,sy=1,sz=1,parent=world){const obj=new THREE.Mesh(g,m);obj.position.set(x,y,z);obj.scale.set(sx,sy,sz);obj.castShadow=true;obj.receiveShadow=true;parent.add(obj);return obj;}
function box(x,y,z,w,h,d,color,parent=world){return mesh(geo.box,typeof color==='object'?color:mat(color),x,y,z,w,h,d,parent);}
let rngSeed=12494;
